parameters.jsCode:
// Parse Claude response into separate social posts

const response = $input.first().json;
let linkedin = '';
let twitterThread = [];

try {
  const text = response.content[0].text.replace(/```json|```/g, '').trim();
  const parsed = JSON.parse(text);
  linkedin = parsed.linkedin || '';
  twitterThread = parsed.twitter_thread || [];
} catch (e) {
  console.log('Parse error:', e.message);
  linkedin = 'ERROR: Check Claude response';
  twitterThread = ['ERROR: Check Claude response'];
}

return [{
  json: {
    linkedin_post: linkedin,
    twitter_thread: twitterThread,
    twitter_hook: twitterThread[0] || '',
    generated_at: new Date().toISOString()
  }
}];
